# Sync example
from redwood.sdk.stream import StreamEventHandler, sync_run_stream

class PrintHandler(StreamEventHandler):
    def on_content(self, event):
        # event.type == 'token' or 'chunk' with 'text' field
        print(event.get('text', ''))

    def on_signal(self, event):
        if event.get('type') == 'done':
            print('stream completed')

    def on_error(self, err):
        print('stream error', err)

handler = PrintHandler()
# source_stream is an iterable of raw server-sent JSON frames
sync_run_stream(handler, source_stream, backpressure_window=5)
